<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {ArrowLeft,GitBranch,Download,CheckCircle2} from 'lucide-vue-next'
import MarkdownView from '~/components/ui/MarkdownView.vue'
import type {ContentPreviewReport,ContentSyncBindings} from '~/shared/content-sync'
definePageMeta({layout:'admin'})
useHead({title:'Git 教程同步 — AttackBox'})
interface Settings {repository:string;branch:string;directory:string;hasToken:boolean;version:number;latest:{id:string;commit:string|null;result:{moduleIds:string[]}|null}|null}
const {data:settings,error:settingsError,refresh}=useLazyFetch<{data:Settings}>('/api/admin/content/repository',{key:'admin:content:repository'})
const form=ref({repository:'',branch:'main',directory:'',token:''}),busy=ref(''),message=ref(''),report=ref<ContentPreviewReport|null>(null),bindings=ref<ContentSyncBindings>({modules:{},chapters:{},questions:{}}),resumeId=ref(''),selected=ref(0)
watch(settings,value=>{if(value){form.value={repository:value.data.repository,branch:value.data.branch,directory:value.data.directory,token:''};resumeId.value=value.data.latest?.id||''}},{immediate:true})
const dirty=computed(()=>!!settings.value&&(form.value.repository!==settings.value.data.repository||form.value.branch!==settings.value.data.branch||form.value.directory!==settings.value.data.directory||!!form.value.token))
const module=computed(()=>report.value?.modules?.[selected.value])
async function perform(label:string,task:()=>Promise<void>){if(busy.value)return;busy.value=label;message.value='';try{await task()}catch(e:any){message.value=e?.data?.message||e?.data?.statusMessage||'请求未确认，可手动查询最近操作结果'}finally{busy.value=''}}
function applyReport(value:ContentPreviewReport){report.value=value;bindings.value=structuredClone(value.bindings||{modules:{},chapters:{},questions:{}});resumeId.value=value.id;selected.value=0}
function candidate(id:string|null){return report.value?.candidates?.find(m=>m.id===id)}
function chapterCandidates(chapterId:string|null){return report.value?.candidates?.flatMap(m=>m.chapters).find(c=>c.id===chapterId)?.questions||[]}
function setBinding(type:keyof ContentSyncBindings,key:string,event:Event){const value=(event.target as HTMLSelectElement).value;if(value)bindings.value[type][key]=value;else delete bindings.value[type][key]}
function save(){void perform('保存配置',async()=>{await $fetch('/api/admin/content/repository',{method:'PUT',body:{...form.value,version:settings.value?.data.version||0}});form.value.token='';await refresh();message.value='配置已保存，尚未连接或拉取'})}
function clearToken(){if(!confirm('清除只读 Token？已经导入的教程不受影响。'))return;void perform('清除凭据',async()=>{await $fetch('/api/admin/content/repository',{method:'PUT',body:{...form.value,token:'',version:settings.value?.data.version,clearToken:true}});await refresh();message.value='凭据已清除'})}
function testConnection(){void perform('测试连接',async()=>{const response=await $fetch<{data:{commit:string}}>('/api/admin/content/test',{method:'POST'});message.value=`连接成功 · ${response.data.commit.slice(0,12)}`})}
function pull(){void perform('拉取并预览',async()=>{applyReport((await $fetch<{data:ContentPreviewReport}>('/api/admin/content/pull',{method:'POST'})).data);await refresh()})}
function resume(){void perform('读取最近预览',async()=>{const latest=(await $fetch<{data:Settings}>('/api/admin/content/repository')).data.latest;if(!latest){message.value='暂无可恢复的 Git 预览';return}resumeId.value=latest.id;applyReport((await $fetch<{data:ContentPreviewReport}>(`/api/admin/content/previews/${latest.id}`)).data)})}
function updateBindings(){void perform('确认关联',async()=>applyReport((await $fetch<{data:ContentPreviewReport}>(`/api/admin/content/previews/${report.value!.id}`,{method:'PATCH',body:{bindings:bindings.value}})).data))}
function discard(){if(!confirm('清除这次预览及临时文件？已导入的模块不会删除。'))return;void perform('清理预览',async()=>{await $fetch(`/api/admin/content/previews/${resumeId.value}`,{method:'DELETE'});report.value=null;resumeId.value='';await refresh();message.value='预览已清理'})}
function importContent(){if(!confirm('确认导入这次预览？已发布模块的内容会立即更新，新模块保持未发布。'))return;void perform('导入内容',async()=>{const response=await $fetch<{data:{moduleIds:string[]}}>(`/api/admin/content/previews/${report.value!.id}/apply`,{method:'POST'});report.value={id:report.value!.id,applied:true,result:response.data};clearNuxtData(k=>k.startsWith('admin:')||k.startsWith('learning:'));await refresh();message.value='导入完成'})}
</script>
<template>
 <div class="git-content-page">
  <NuxtLink class="back" to="/admin/modules"><ArrowLeft :size="14"/>学习模块</NuxtLink>
  <header class="page-header"><div><h1>Git 教程同步</h1><p>从私有仓库手动导入教程。保存配置不会拉取或发布。</p></div><a class="button" href="/api/admin/content/template" download="教程模板.md"><Download :size="15"/>下载 MD 模板</a></header>
  <p v-if="message" class="notice" role="status">{{message}}</p>
  <p v-if="settingsError" class="notice" role="alert">配置读取失败。<button @click="refresh()">重新读取</button></p>
  <section class="panel"><h2><GitBranch :size="17"/>仓库设置</h2>
   <form @submit.prevent="save"><fieldset :disabled="!!busy || !settings"><div class="settings-grid">
    <label>GitHub 私有仓库<input v-model="form.repository" placeholder="owner/repository" autocomplete="off" required/></label>
    <label>分支<input v-model="form.branch" placeholder="main" required/></label>
    <label>教程目录<input v-model="form.directory" placeholder="留空为仓库根目录"/></label>
    <label class="token-field">只读 Token <span>{{settings?.data.hasToken?'已配置，留空保持不变':'未配置'}}</span><input v-model="form.token" type="password" autocomplete="new-password" placeholder="仅授权当前仓库的 Contents: Read-only"/></label>
   </div><div class="actions"><button class="button" type="submit">保存配置</button><button class="button" type="button" :disabled="dirty || !settings?.data.hasToken" @click="testConnection">测试连接</button><button class="button primary" type="button" :disabled="dirty || !settings?.data.hasToken" @click="pull">拉取并预览</button><button v-if="settings?.data.hasToken" class="text-button" type="button" @click="clearToken">清除凭据</button><span v-if="busy" role="status">{{busy}}…</span></div></fieldset></form>
  </section>
  <div class="resume"><span class="hint">最近预览{{settings?.data.latest?.commit ? ` · ${settings.data.latest.commit.slice(0,12)}` : ''}}</span><button class="button" :disabled="!!busy" @click="resume">查询最近预览结果</button><button v-if="resumeId" class="text-button" :disabled="!!busy" @click="discard">清理预览</button></div>
  <section v-if="report?.applied" class="panel"><h2><CheckCircle2 :size="18"/>内容已导入</h2><div class="actions"><NuxtLink v-for="id in report.result?.moduleIds" :key="id" class="button" :to="`/admin/modules/${id}`">查看模块</NuxtLink></div></section>
  <template v-else-if="report">
   <section class="panel"><div class="preview-head"><div><h2>导入预览</h2><p>{{report.commit?`Commit ${report.commit.slice(0,12)}`:'本地内容快照'}} · {{report.modules?.length}} 个模块</p></div><button class="button primary" :disabled="!!busy || report.stale || !!report.conflicts?.length" @click="importContent">确认导入</button></div><p class="hint">确认后已发布内容立即更新；新模块保持未发布。这里不执行靶机镜像拉取或构建。</p><p v-if="report.stale" class="notice">线上内容已变化，请重新拉取预览。</p><ul v-if="report.conflicts?.length" class="conflicts"><li v-for="item in report.conflicts" :key="item">{{item}}</li></ul><p v-for="missing in report.missingModules" :key="missing.id" class="hint">来源缺失：{{missing.path}}。保留原内容，可在模块详情下架。</p></section>
   <div class="preview-grid"><aside class="panel"><button v-for="(item,index) in report.modules" :key="item.path" class="module-choice" :class="{selected:selected===index}" @click="selected=index"><strong>{{item.preview.title}}</strong><span>{{item.id?(item.changed?'更新':'无内容变化'):'新增'}} · {{item.preview.chapters.length}} 章</span></button></aside>
    <section v-if="module" class="panel module-preview"><h2>{{module.preview.title}}</h2><p class="hint">{{module.path}}</p><p>{{module.preview.summary}}</p><MarkdownView :content="module.preview.descriptionMarkdown" :image-urls="module.preview.imageUrls"/>
     <details class="bindings"><summary>关联已有内容（首次接管或改名时使用）</summary><label>关联模块<select :value="bindings.modules[module.path]||''" @change="setBinding('modules',module.path,$event)"><option value="">{{module.id?'沿用当前关联':'新建模块'}}</option><option v-for="c in report.candidates" :key="c.id" :value="c.id">{{c.title}}</option></select></label>
      <p class="hint">先关联模块并点击确认，再关联它的章节和题目。每次确认只更新预览，不写入教程。</p>
      <div v-for="ch in module.chapters" :key="ch.key" class="chapter-binding"><label>{{ch.title}}<select :value="bindings.chapters[ch.key]||''" @change="setBinding('chapters',ch.key,$event)"><option value="">{{ch.id?'沿用当前关联':'新增章节'}}</option><option v-for="c in candidate(module.id)?.chapters" :key="c.id" :value="c.id">{{c.title}}</option></select></label><label v-for="q in ch.questions" :key="q.key">{{q.prompt}}<select :value="bindings.questions[q.key]||''" @change="setBinding('questions',q.key,$event)"><option value="">{{q.id?'沿用当前关联':'新增题目'}}</option><option v-for="c in chapterCandidates(ch.id)" :key="c.id" :value="c.id">{{c.prompt}}</option></select></label></div>
      <button class="button" :disabled="!!busy" @click="updateBindings">确认关联并更新预览</button>
     </details>
     <details v-for="ch in module.preview.chapters" :key="ch.title" class="chapter-preview"><summary>{{ch.title}}<span>{{ch.access==='public'?'公开':'登录可读'}}<template v-if="ch.durationMinutes"> · {{ch.durationMinutes}} 分钟</template></span></summary><MarkdownView :content="ch.bodyMarkdown" :image-urls="module.preview.imageUrls"/><div v-if="ch.questions.length" class="preview-questions"><h3>章节练习</h3><MarkdownView v-for="(q,index) in ch.questions" :key="index" :content="q.promptMarkdown" :image-urls="module.preview.imageUrls"/></div></details>
    </section>
   </div>
  </template>
 </div>
</template>
<style scoped>
.back{display:inline-flex;align-items:center;gap:6px;color:var(--muted);font-size:12px;text-decoration:none;margin-bottom:18px}.page-header,.preview-head{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:24px}h1{font-size:26px;font-weight:650;margin:0}h2{font-size:16px;font-weight:600;margin:0 0 18px;display:flex;align-items:center;gap:8px}h3{font-size:14px}.page-header p,.hint,.preview-head p{font-size:12px;color:var(--muted);line-height:1.8}.panel{border:1px solid var(--line);border-radius:10px;background:var(--paper);padding:24px;margin-bottom:20px}fieldset{border:0;padding:0;margin:0;min-width:0}.settings-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:20px}.token-field{grid-column:1/3}.token-field span{font-size:11px;color:var(--muted);font-weight:400}label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:550}input,select{height:38px;width:100%;min-width:0;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--ink);font-size:12px}.actions{display:flex;align-items:center;gap:10px;margin-top:20px}.actions>span{font-size:12px;color:var(--muted)}.button{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:9px 13px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink);font-size:12px;cursor:pointer;text-decoration:none}.primary{background:var(--green);color:var(--on-accent);border-color:var(--green)}button:disabled{opacity:.45;cursor:default}.text-button{border:0;background:transparent;color:var(--muted);font-size:12px;cursor:pointer}.notice{padding:12px 16px;background:var(--soft);border-radius:6px;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.resume{display:flex;gap:12px;align-items:flex-end;margin:20px 0}.resume label{width:360px}.conflicts{font-size:12px;color:var(--error-ink);line-height:1.8}.preview-grid{display:grid;grid-template-columns:230px minmax(0,1fr);gap:20px;align-items:start}.preview-grid>aside{padding:8px}.module-choice{display:flex;flex-direction:column;gap:5px;width:100%;padding:12px;text-align:left;border:0;border-radius:6px;background:transparent;color:var(--ink);cursor:pointer}.module-choice span{font-size:11px;color:var(--muted)}.module-choice.selected{background:var(--soft)}.bindings{padding:14px;background:var(--bg);border-radius:6px;margin:20px 0}.bindings summary{font-size:12px;cursor:pointer}.bindings label{margin-top:14px}.chapter-binding{padding-top:12px;margin-top:12px;border-top:1px solid var(--line)}.chapter-preview{border-top:1px solid var(--line);margin-top:20px;padding-top:18px}.chapter-preview summary{cursor:pointer;font-size:14px;font-weight:550}.chapter-preview summary span{float:right;color:var(--muted);font-size:11px;font-weight:400}.preview-questions{border-top:1px solid var(--line);margin-top:20px}:focus-visible{outline:2px solid var(--green);outline-offset:3px}
</style>
